using System.ComponentModel.DataAnnotations;using System.ComponentModel.DataAnnotations.Schema;namespace SyWater.Places.Infrastructure.Persistence.Entities;[Table("activity_log", Schema = "places")]public sealed class PlaceActivityEntity{    [Key, Column("id"), DatabaseGenerated(DatabaseGeneratedOption.Identity)] public long Id { get; set; }    [Column("place_id")] public Guid PlaceId { get; set; }    [Column("owner_id")] public Guid OwnerId { get; set; }    [Column("action")] public string Action { get; set; } = "";    [Column("metadata")] public string? Metadata { get; set; }    [Column("created_at")] public DateTime CreatedAt { get; set; }}